/* src/dr/10_dr_html.js: the tokenizer, the page parser, the outline, the audit in each of its seven areas and its score,
   contrast, design tokens, sanitize, sitemaps, the redirect map and its four formats, and the static site bundle.
   Fixtures are hand written; the Site Forge fixture follows the markup FORGE_COMPILE writes and the css CMS.brandCss ships. */
import fs from 'node:fs';
import path from 'node:path';
import { makeContext, load, suite, SRC } from './lib/load.mjs';
const { ok, eq, done } = suite();
const ctx = makeContext(); load(ctx, ['dr/00_dr_core.js', 'dr/10_dr_html.js']);
const H = ctx.DRHVAC.html;
const S = 'script';
/* every audit run below is recorded, so the last check can show that each finding the source can raise was raised here */
const raised = new Set(), auditFn = H.audit; H.audit = (html, o) => { const r = auditFn(html, o); r.findings.forEach(f => raised.add(f.id)); return r; };
const ids = a => a.findings.map(f => f.id);
const has = (a, id) => a.findings.some(f => f.id === id);
const find = (a, id) => a.findings.find(f => f.id === id);

/* ---- the file can be carried inline ---- */
const source = fs.readFileSync(path.join(SRC, 'dr/10_dr_html.js'), 'utf8');
ok(!/<\/script/i.test(source) && !/<script/i.test(source) && !source.includes('<!--'), 'the source never spells out a script tag or a comment opener, so the single file edition can inline it');

/* ---- tokenizer ---- */
let src = `<!DOCTYPE html><P class=a title="x > y" data-q='1' DISABLED>Tom &amp; Jerry &#169; &#x2014; &bogus;<br/><${S}>if (a<b) { x = "</p>"; }</${S}><!-- c > d --> 1 < 2 <a href=/path/ id=k>go</a></p>`;
let T = H.tokens(src);
eq(T.map(t => t.t + (t.name ? ':' + t.name : '')), ['doctype', 'open:p', 'text', 'open:br', 'open:script', 'text', 'close:script', 'comment', 'text', 'text', 'open:a', 'text', 'close:a', 'close:p'], 'tags, text, comment and doctype come out in order, names lower cased');
eq(T[1].attrs, { class: 'a', title: 'x > y', 'data-q': '1', disabled: '' }, 'quoted values may hold ">", unquoted and single quoted values and bare attributes are read');
eq(T[2].text, 'Tom & Jerry © — &bogus;', 'named and numeric entities are decoded, an unknown one is left as written');
ok(T[3].self && !T[1].self, 'a void element counts as closed');
ok(T[5].raw && T[5].text === 'if (a<b) { x = "</p>"; }', 'script text is raw up to its own closing tag, whatever it contains');
eq([T[7].text, T[8].text + T[9].text], [' c > d ', ' 1 < 2 '], 'a comment may hold ">", and a "<" that opens nothing is text');
eq(T[10].attrs, { href: '/path/', id: 'k' }, 'an unquoted value may end in a slash');
ok(T.map(t => src.slice(t.pos, t.end)).join('') === src, 'the tokens cover the source exactly: slicing pos to end rebuilds it');
T = H.tokens(`<title>A &amp; B</title><textarea><b>x</b></textarea><${S} src=x.js /><p>after</p></${S}><div a=1 a=2 =z>`);
eq([T[1].text, T[4].text, T[4].raw], ['A & B', '<b>x</b>', undefined], 'title and textarea are text only, with entities decoded');
ok(T[6].name === 'script' && !T[6].self && T[7].raw && T[7].text === '<p>after</p>', 'a self closing slash on a script is ignored, as browsers do');
eq(T[T.length - 1].attrs, { a: '1' }, 'the first of a repeated attribute wins and a stray "=" is skipped');
eq(H.tokens('text <b unfinished').map(t => t.t), ['text', 'open'], 'a tag that never closes runs to the end');
eq(H.tokens('a <!-- never closed').map(t => t.t), ['text', 'comment'], 'so does a comment');
eq(H.tokens('').length + H.tokens(null).length, 0, 'empty input gives no tokens');
eq(H.decode('&lt;p&gt; &quot;x&quot; &#39;y&#39; &nbsp;z'), '<p> "x" \'y\'  z', 'decode');

/* ---- parse: a whole document ---- */
const DOC = `<!doctype html><html lang="en-US"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AC Repair in Plano, TX | Northside Comfort</title><meta name="description" content="Same day AC repair in Plano."><meta name="robots" content="index,follow"><meta property="og:title" content="AC Repair"><link rel="canonical" href="https://www.northside.test/ac-repair/"><link rel="stylesheet" href="/theme.css"><${S} async src="https://tags.test/t.js"></${S}><${S} src="/app.js"></${S}><${S} type="module" src="/m.js"></${S}><style>.a{color:red}</style></head>
<body><header><nav aria-label="Main"><a href="/">Home</a><a href="https://www.northside.test/services/">Services</a></nav></header><main>
<section id="hero"><h1>AC Repair in <em>Plano</em></h1><p>Fast help. <a class="btn" href="tel:+19725550100">Call (972) 555 0100</a> <a href="mailto:hi@northside.test">Email</a></p><picture><source srcset="h.avif" type="image/avif"><img src="hero.jpg" alt="Technician at a condenser" width="1600" height="900" fetchpriority="high"></picture></section>
<section><h2 id="more">More</h2><img src="b.png" loading="lazy"><img src="c.webp" alt="" role="presentation"><a href="https://other.test/x">Partner</a><a href="#more">Up</a><a href="#">Nothing</a><a>named anchor</a><p hidden>secret words</p><div style="display:none">also hidden</div><noscript>no script text</noscript>
<form id="f" action="/lead" method="POST"><input type="hidden" name="page" value="x"><input type="text" name="website" tabindex="-1" style="position:absolute;left:-9999px"><label>Full name <input name="name" required></label><label for="ph">Phone</label><input id="ph" type="tel" name="phone" autocomplete="tel"><select name="when" aria-label="When"><option>Today</option></select><textarea name="msg" placeholder="What happened"></textarea><label><input type="checkbox" name="consent" value="yes"> I agree to be contacted</label><button>Request service</button></form>
<iframe src="https://maps.test/embed" title="Map" loading="lazy"></iframe><video src="v.mp4" autoplay muted></video><details><summary>How fast?</summary><p>Same day.</p></details><div id="dup"></div><span id="dup" tabindex="2"></span></section></main><footer role="contentinfo">Northside Comfort</footer>
<${S}>var x = 1 < 2;</${S}><${S} type="application/ld+json">{"@context":"https://schema.org","@graph":[{"@type":"HVACBusiness","name":"Northside Comfort"}]}</${S}><${S} type="application/ld+json">{oops</${S}></body></html>`;
let P = H.parse(DOC);
eq([P.lang, P.title, P.canonical, P.robots, P.viewport, P.charset, P.fragment], ['en-US', 'AC Repair in Plano, TX | Northside Comfort', 'https://www.northside.test/ac-repair/', 'index,follow', 'width=device-width,initial-scale=1', 'utf-8', false], 'the head: lang, title, canonical, robots, viewport, charset');
eq([P.metas.description, P.metas['og:title']], ['Same day AC repair in Plano.', 'AC Repair'], 'meta tags by name or property');
eq(P.headings, [{ level: 1, text: 'AC Repair in Plano', id: '' }, { level: 2, text: 'More', id: 'more' }], 'headings with their text flattened');
eq(P.images.map(i => [i.src, i.alt, i.hasAlt, i.width, i.loading, i.fetchpriority, i.inPicture, i.decorative, i.fold]), [['hero.jpg', 'Technician at a condenser', true, '1600', '', 'high', true, false, true], ['b.png', '', false, '', 'lazy', '', false, false, false], ['c.webp', '', true, '', '', '', false, true, false]], 'images: alt present or absent, size, loading, priority, picture, and whether they sit in the first section');
eq(P.anchors.map(a => [a.text, a.kind, a.fold]), [['Home', 'internal', true], ['Services', 'internal', true], ['Call (972) 555 0100', 'tel', true], ['Email', 'mailto', true], ['Partner', 'external', false], ['Up', 'anchor', false], ['Nothing', 'empty', false], ['named anchor', 'empty', false]], 'links by kind; the canonical host tells internal from external');
ok(P.anchors[2].btn && !P.anchors[0].btn && P.anchors[7].href === null, 'a button class marks a call to action; an a without href has a null href');
const F = P.forms[0];
eq([F.action, F.method, F.fields.length, F.hasConsent, F.consentPrechecked, F.submitText], ['/lead', 'post', 7, true, false, 'Request service'], 'the form: where it posts, its fields, the consent box and the submit text');
eq(F.fields.map(f => [f.name, f.type, f.label, f.required, f.offscreen]), [['page', 'hidden', '', false, true], ['website', 'text', '', false, true], ['name', 'text', 'Full name', true, false], ['phone', 'tel', 'Phone', false, false], ['when', 'select', '', false, false], ['msg', 'textarea', '', false, false], ['consent', 'checkbox', 'I agree to be contacted', false, false]], 'fields take their label from a wrapping label or a for attribute; hidden and honeypot fields are marked off screen');
eq([F.fields[4].ariaLabel, F.fields[5].placeholder, F.fields[3].autocomplete], ['When', 'What happened', 'tel'], 'aria-label, placeholder and autocomplete are kept');
eq(P.scripts.map(s => [s.src, s.async, s.defer, s.module, s.inHead, s.inlineBytes > 0]), [['https://tags.test/t.js', true, false, false, true, false], ['/app.js', false, false, false, true, false], ['/m.js', false, false, true, true, false], ['', false, false, false, false, true]], 'scripts: where they sit and how they load; JSON-LD is not counted as a script');
eq(P.styles.map(s => [s.href, s.inHead, s.inlineBytes]), [['/theme.css', true, 0], ['', true, 13]], 'stylesheets and style blocks');
eq([P.jsonld.length, P.jsonld[0]['@graph'][0].name, P.jsonldErrors.length], [1, 'Northside Comfort', 1], 'JSON-LD is parsed, and a block that does not parse is reported');
eq([P.landmarks, P.sections], [{ main: 1, header: 1, nav: 1, footer: 1 }, 2], 'landmarks by element or role');
ok(!/secret|also hidden|no script text|var x|color:red/.test(P.text) && /Fast help\. Call \(972\) 555 0100 Email/.test(P.text), 'the text is what a visitor reads: nothing hidden, no script, no style');
eq([P.ids.dupes, P.tabindexPositive, P.iframes.length, P.media[0].autoplay && P.media[0].muted, P.details[0].summary, P.buttons[0].text], [['dup'], 1, 1, true, 'How fast?', 'Request service'], 'duplicate ids, positive tabindex, frames, media, expandable items, buttons');
ok(P.words > 15 && P.domNodes > 40 && P.bytes === Buffer.byteLength(DOC) && !Object.keys(P).includes('_x'), 'counts are plausible and the working data stays out of the listed result');

/* ---- parse: a fragment, and the domain option ---- */
P = H.parse('<section><h1>One</h1><a href="https://www.northside.test/a/">in</a><a href="https://else.test/">out</a></section><section><a href="tel:1">t</a></section>', { domain: 'northside.test' });
eq([P.fragment, P.anchors.map(a => a.kind), P.anchors.map(a => a.fold)], [true, ['internal', 'external', 'tel'], [true, true, false]], 'markup without html, head or body is a fragment; the first section is the fold; domain decides internal');
P = H.parse('<div>' + 'word '.repeat(200) + '<a href="/late/">late</a></div><a href="/x/" id="top">x</a>');
ok(P.anchors[0].fold === false, 'without sections the fold ends after the first 700 characters of text');
ok(H.parse('<p>x</p>', { fragment: false }).fragment === false && H.words('<p>one two <b>three</b></p><style>p{}</style>') === 3 && H.textOf('<p>a<br>b</p><p>c</p>') === 'a b c', 'fragment can be forced; words and textOf');

/* ---- outline ---- */
let out = H.outline(DOC);
ok(/^title: AC Repair in Plano, TX \| Northside Comfort \(42 characters\)/.test(out) && /meta description: Same day AC repair in Plano\. \(28 characters\)/.test(out), 'the outline opens with the title and the description and their lengths');
ok(/\[header\]\n\s+\[nav\]\n\s+links: Home, Services/.test(out) && /\[section#hero\]\n\s+text · 1 words\n\s+h1 "AC Repair in Plano" · 7 words · 1 link · phone link "Call \(972\) 555 0100" · image "Technician at a condenser"/.test(out), 'landmarks and sections in order, the nav links by name, and what sits under the h1', out.split('\n').slice(2, 9).join(' / '));
ok(/image without alt \(b\.png\)/.test(out) && /image \(decorative, empty alt\)/.test(out) && /\[form#f action \/lead\]/.test(out) && /fields: Full name\*, Phone, When, msg, I agree to be contacted · consent checkbox · submit "Request service"/.test(out) && /iframe maps\.test · video/.test(out) && /question "How fast\?" · 2 words/.test(out), 'images without alt, the form with its fields, frames and questions in expandable items are called out', out);
ok(/totals: \d+ words · 2 headings · 3 images \(1 without alt\) · links: 2 internal, 1 external, 1 phone · 1 forms · JSON-LD: HVACBusiness$/.test(out), 'and it closes with the totals', out.split('\n').pop());
const longPage = '<main>' + Array.from({ length: 300 }, (_, i) => `<section id="s${i}"><h2>Heading ${i}</h2><p>some words here</p></section>`).join('') + '</main>';
out = H.outline(longPage, { maxLines: 40 });
ok(out.split('\n').length <= 41 && /lines left out of the middle/.test(out) && /h2 "Heading 0"/.test(out) && /totals:/.test(out), 'a long page is cut in the middle, keeping the start and the totals', out.split('\n').length);

/* ---- audit: a well built landing page, as a whole document ---- */
const para = n => Array.from({ length: n }, (_, i) => `<p>Every repair is priced in writing before work starts, and the technician explains what failed and why in plain words on visit ${i + 1}.</p>`).join('');
const GOOD = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AC Repair in Plano, TX | Northside Comfort</title><meta name="description" content="Same day AC repair for Plano homes from Northside Comfort. Written prices before work starts. TDLR Lic TACLA00000E. Call or book online."><link rel="canonical" href="https://www.northside.test/lp-ac-repair-plano/"><meta name="robots" content="noindex,follow"><meta property="og:title" content="AC Repair in Plano"><meta property="og:image" content="https://www.northside.test/og.webp"><style>body{font-family:system-ui;color:#1b1b1a;background:#fff}.hero{background:#173a69;color:#fff}.btn{display:inline-block;padding:14px 22px;background:#edd21c;color:#112337;border-radius:8px}.eyebrow{color:#fff}</style></head>
<body><main><section class="hero" id="top"><p class="eyebrow">Northside Comfort · Plano</p><h1>AC Repair in Plano, TX</h1><p>Same day repair, priced in writing before work starts. Open Monday to Saturday 7 am to 8 pm.</p><p><a class="btn" href="tel:+19725550100">Call (972) 555 0100</a> <a class="btn" href="#contact">Book a repair visit</a></p><img src="https://www.northside.test/img/plano-ac.webp" alt="Northside Comfort technician servicing a condenser in Plano" width="1600" height="1000" fetchpriority="high"></section>
<section><h2>The short answer</h2>${para(6)}</section>
<section><h2>Questions before you book</h2><details><summary>How fast can you come out?</summary><p>Most days the same day.</p></details><details><summary>Is the price in writing?</summary><p>Yes, before any work starts.</p></details></section>
<section id="contact"><h2>Request a visit</h2><form action="/wp-json/forge/v1/lead" method="post"><label>Full name<input type="text" name="name" required></label><label>Phone<input type="tel" name="phone" required></label><label>Tell us what happened<textarea name="message"></textarea></label><label><input type="checkbox" name="consent" value="yes" required> By submitting, you agree that we may contact you by phone or text about your request.</label><button type="submit" class="btn">Request service</button></form><p><small>Northside Comfort. TDLR Lic TACLA00000E.</small></p></section></main>
<${S} type="application/ld+json">{"@context":"https://schema.org","@graph":[{"@type":"HVACBusiness","name":"Northside Comfort","telephone":"+19725550100","address":{"@type":"PostalAddress","addressLocality":"Plano","addressRegion":"TX"}},{"@type":"FAQPage","mainEntity":[{"@type":"Question","name":"How fast can you come out?","acceptedAnswer":{"@type":"Answer","text":"Most days the same day."}},{"@type":"Question","name":"Is the price in writing?","acceptedAnswer":{"@type":"Answer","text":"Yes, before any work starts."}}]}]}</${S}></body></html>`;
const BRAND = { name: 'Northside Comfort', phone: '(972) 555 0100', lic: 'TACLA00000E', domain: 'northside.test' };
let a = H.audit(GOOD, { url: 'https://www.northside.test/lp-ac-repair-plano/', kind: 'landing', brand: BRAND });
ok(a.score >= 90 && a.grade === 'A' && a.counts.block === 0 && a.counts.warn === 0, 'a well built landing page scores in the 90s with no blocks and no warnings', `${a.score} ${JSON.stringify(a.counts)} ${ids(a).join(',')}`);
ok(has(a, 'seo.noindex') && find(a, 'seo.noindex').info === true && find(a, 'seo.noindex').sev === 'note', 'noindex on a campaign landing page is noted as expected, at no cost');
eq([a.facts.titleLength, a.facts.h1, a.facts.phoneInFirstSection, a.facts.forms, a.facts.altCoverage, a.facts.jsonldTypes, a.facts.contrast.failing, a.kind, a.fragment], [42, ['AC Repair in Plano, TX'], true, 1, 100, ['HVACBusiness', 'FAQPage'], 0, 'landing', false], 'the facts the findings rest on come back with the result');
ok(a.facts.contrast.checked > 5 && Object.keys(a.areas).join() === 'seo,a11y,perf,cro,content,schema,security' && a.areas.a11y.score === 100, 'contrast was actually checked on this page, and every area has a score');
ok(a.findings.every(f => f.id && f.area && /^(block|warn|note)$/.test(f.sev) && f.msg && typeof f.evidence === 'string' && typeof f.fix === 'string'), 'every finding has an id, an area, a severity, a message, evidence and a fix');

/* ---- audit: a page in the shape the Site Forge compiles, with the css the Publish module ships ---- */
const FORGE_CSS = ':root{--forge-p:#173a69;--forge-a:#0b6f6d;--forge-d:#112337;--forge-t:#e8ebf0}.forge-section{padding:56px 20px}.forge-inner{max-width:1140px;margin:0 auto}.forge-tint{background:var(--forge-t,#eef2f6)}.forge-brand{background:var(--forge-p,#13243a);color:#fff}.forge-brand h2{color:#fff}.forge-eyebrow{color:var(--forge-a,#0b6f6d);font-weight:700}.forge-btn{display:inline-block;padding:14px 22px;border-radius:8px}.forge-btn-primary{background:var(--forge-p,#13243a);color:#fff}.forge-btn-secondary{background:var(--forge-a,#0b6f6d);color:#fff}.forge-facts div{background:#fff}.forge-facts dt{font-size:34px;color:var(--forge-p,#13243a)}.forge-sticky{display:none}@media(max-width:767px){.forge-sticky{display:flex}.forge-sticky-call{background:var(--forge-a,#0b6f6d);color:#fff}}';
const FORGE = `<section id="hero" class="forge-section forge-sec-hero forge-light"><div class="forge-inner"><div class="forge-split"><div><p class="forge-eyebrow">Northside Comfort · Plano</p><h1>AC Repair, Replacement and Heating in Plano, TX</h1><p class="forge-lede">Repairs priced before work starts. TDLR Lic TACLA00000E.</p><p class="forge-ctas"><a class="forge-btn forge-btn-primary" href="#contact">Book service</a> <a class="forge-btn forge-btn-secondary" href="tel:+19725550100">Call (972) 555 0100</a> </p><ul class="forge-trust"><li>TDLR Lic TACLA00000E</li><li>Written prices before work starts</li><li>Open Monday to Saturday 7 am to 8 pm</li></ul></div><div><img src="https://www.northside.test/wp-content/uploads/plano-hvac.webp" alt="Northside Comfort heating and air conditioning service in Plano, Texas" width="1600" height="1000" fetchpriority="high" decoding="async"></div></div></div></section>
<section id="answer" class="forge-section forge-sec-answer forge-tint"><div class="forge-inner forge-narrow"><h2>Who services heating and air conditioning in Plano?</h2><p class="forge-answer"><strong>Northside Comfort repairs and replaces air conditioners, furnaces and heat pumps in Plano.</strong></p></div></section>
<section id="facts" class="forge-section forge-sec-key_facts forge-tint"><div class="forge-inner"><h2>Plano by the numbers</h2><dl class="forge-facts"><div><dt>41%</dt><dd>of Plano central systems are 15 years or older <small>(Estimate from Census housing data)</small></dd></div></dl></div></section>
<section id="detail" class="forge-section forge-sec-rich_text forge-light"><div class="forge-inner forge-narrow"><h2>The Plano picture</h2>${para(20)}<p>See <a href="/ac-repair/">AC repair</a> and <a href="/furnace-repair/">furnace repair</a>.</p></div></section>
<section id="faq" class="forge-section forge-sec-faq forge-light"><div class="forge-inner forge-narrow"><h2>Questions Plano homeowners ask</h2><details class="forge-faq"><summary><h3>How fast can you come out?</h3></summary><p>Most days the same day.</p></details><details class="forge-faq"><summary><h3>Do you price before work starts?</h3></summary><p>Yes, in writing.</p></details></div></section>
<section id="cta" class="forge-section forge-sec-cta_band forge-brand"><div class="forge-inner"><h2>Book heating or cooling service in Plano.</h2><p>Repairs priced before work starts.</p><p class="forge-ctas"><a class="forge-btn forge-btn-primary" href="#contact">Book service</a> </p></div></section>
<section id="contact" class="forge-section forge-sec-form forge-tint"><div class="forge-inner forge-narrow"><h2>Request service</h2><form class="forge-form" method="post" action="/wp-json/forge/v1/lead" data-forge-form><input type="hidden" name="page" value="plano-hvac"><input type="text" name="website" tabindex="-1" autocomplete="off" aria-hidden="true" style="position:absolute;left:-9999px"><label>Full name<input type="text" name="name" required></label><label>Phone<input type="tel" name="phone" required></label><label>Email<input type="email" name="email" required></label><label>Tell us what happened<textarea name="message"></textarea></label><label class="forge-consent"><input type="checkbox" name="consent" value="yes" required> By submitting, you agree that we may contact you by phone, text or email about your request.</label><button type="submit" class="forge-btn forge-btn-primary">Request service</button><p class="forge-form-msg" aria-live="polite"></p></form><${S}>(function(){var f=document.querySelector("[data-forge-form]");})();</${S}></div></section>
<div class="forge-sticky"><a class="forge-sticky-call" href="tel:+19725550100">Call now</a><a class="forge-sticky-cta" href="#contact">Book service</a></div>`;
const SCHEMA = { '@context': 'https://schema.org', '@graph': [{ '@type': 'HVACBusiness', name: 'Northside Comfort', telephone: '+19725550100', address: { '@type': 'PostalAddress', addressLocality: 'Plano' } }, { '@type': 'FAQPage', mainEntity: [{ '@type': 'Question', name: 'How fast can you come out?' }, { '@type': 'Question', name: 'Do you price before work starts?' }] }] };
a = H.audit(FORGE, { kind: 'city', css: FORGE_CSS, schema: SCHEMA, brand: BRAND });
ok(a.score >= 97 && a.counts.block === 0 && a.counts.warn === 0 && a.findings.every(f => f.info), 'a compiled Site Forge page audits clean: only things worth knowing, none of them a fault', `${a.score} ${ids(a).join(',')}`);
ok(a.fragment && has(a, 'seo.fragment_scope') && a.skipped.includes('title') && a.skipped.includes('canonical') && !ids(a).some(i => /title_missing|meta_missing|viewport|lang_missing|canonical|og_missing|main_missing/.test(i)), 'as a fragment it is not marked down for the head tags the site around it sets, and the result says what was skipped');
ok(has(a, 'cro.sticky_bar') && a.facts.stickyBar && a.facts.formFields === 5 && a.facts.contrast.checked > 0 && a.facts.contrast.failing === 0, 'the sticky call bar is noted, the honeypot is not counted as a field, and the colors the css resolves pass');
ok(H.audit(FORGE, { kind: 'city', brand: BRAND }).findings.some(f => f.id === 'schema.not_in_markup' && f.info) && /sets no colors of its own/.test(find(H.audit(FORGE, { kind: 'city' }), 'a11y.contrast_unknown').msg), 'without the css and the schema beside it the audit says what it could not check instead of guessing');
/* the same page with a yellow accent: the shipped css puts white text on it */
a = H.audit(FORGE, { kind: 'city', css: FORGE_CSS.replace('--forge-a:#0b6f6d', '--forge-a:#edd21c'), schema: SCHEMA, brand: BRAND, canvas: '#ffffff' });
ok(has(a, 'a11y.contrast') && /#ffffff on #edd21c is 1\.52 to 1 \(needs 4\.5\)/.test(find(a, 'a11y.contrast').evidence) && /#edd21c on #ffffff/.test(find(a, 'a11y.contrast').evidence), 'white text on a yellow accent button, and yellow text on a white canvas, are caught with their ratios', find(a, 'a11y.contrast') && find(a, 'a11y.contrast').evidence);

/* ---- audit: a page that gets everything wrong, each area tripping its own findings ---- */
const BAD = `<html><head><title>Home</title><meta name="viewport" content="width=device-width, user-scalable=no"><meta name="robots" content="noindex"><link rel="canonical" href="/ac"><${S} src="https://cdn.one.test/a.js"></${S}><${S} src="https://cdn.two.test/b.js"></${S}><${S} src="https://cdn.three.test/c.js"></${S}><${S} src="https://cdn.four.test/d.js"></${S}><link rel="stylesheet" href="https://fonts.googleapis.com/css?family=Roboto"><style>.hero{background:#fff;color:#aaa}@font-face{font-family:X;src:url(x.woff2)}</style></head><body>
<div class="hero"><h3>Welcome</h3><h1>Best AC</h1><h1>Second</h1><p>Lorem ipsum dolor sit amet. Call 972-555-0100 today.</p><img src="http://img.test/hero.jpg" loading="lazy"><a href="#">click here</a><a href="/x"><img src="i.png"></a><a href="#missing">jump</a><a class="btn" href="/a">A</a><a class="btn" href="/b">B</a><a class="btn" href="/c">C</a></div>
<h5>Deep</h5><div id="dup"></div><div id="dup"></div><input name="q" placeholder="Search" tabindex="3"><video autoplay src="v.mp4"></video><iframe src="https://maps.test/embed"></iframe><details><p>no summary</p></details>
<form action="/send"><input type="tel" name="phone"><input name="a"><input name="b"><input name="c"><input name="d"><input name="e"><input name="f"><input name="g"><input name="h"><label><input type="checkbox" name="agree" checked> I agree</label><input type="submit" value="Submit"></form>
<${S} type="application/ld+json">{"@type":"LocalBusiness","aggregateRating":{"ratingValue":5}}</${S}><${S} type="application/ld+json">{broken</${S}><${S} type="application/ld+json">{"@type":"FAQPage","mainEntity":[{"@type":"Question","name":"Hidden question?"}]}</${S}><${S} type="application/ld+json">{"@type":"Product","offers":{"price":"99"}}</${S}>
</body></html>`;
a = H.audit(BAD, { url: 'https://www.bad.test/', kind: 'service', brand: BRAND, headers: { 'content-type': 'text/html' } });
const want = {
  seo: ['seo.noindex', 'seo.title_length', 'seo.meta_missing', 'seo.canonical_relative', 'seo.h1_multiple', 'seo.heading_order', 'seo.link_text', 'seo.thin_content', 'seo.charset_missing', 'seo.og_missing'],
  a11y: ['a11y.zoom_blocked', 'a11y.lang_missing', 'a11y.main_missing', 'a11y.heading_skip', 'a11y.img_alt', 'a11y.link_name', 'a11y.duplicate_ids', 'a11y.tabindex_positive', 'a11y.autoplay', 'a11y.iframe_title', 'a11y.details_summary', 'a11y.field_label', 'a11y.contrast'],
  perf: ['perf.img_dimensions', 'perf.hero_lazy', 'perf.blocking_scripts', 'perf.img_format', 'perf.third_party', 'perf.fonts'],
  cro: ['cro.consent_prechecked', 'cro.phone_missing', 'cro.form_fields', 'cro.trust_license', 'cro.competing_ctas', 'cro.submit_label', 'cro.trust_name'],
  content: ['content.placeholder', 'content.empty_links', 'content.broken_anchor', 'content.phone_not_linked'],
  schema: ['schema.invalid_json', 'schema.business_fields', 'schema.self_review', 'schema.faq_mismatch', 'schema.price_claim'],
  security: ['security.hsts_missing', 'security.mixed_content', 'security.nosniff_missing', 'security.frame_options'],
};
for (const area of Object.keys(want)) { const miss = want[area].filter(id => !has(a, id)); ok(!miss.length, `the bad page trips the ${area} findings: ${want[area].map(x => x.split('.')[1]).join(', ')}`, miss.length ? 'missing ' + miss.join(', ') : undefined); }
eq(['seo.noindex', 'a11y.zoom_blocked', 'cro.consent_prechecked', 'content.placeholder'].map(id => find(a, id).sev), ['block', 'block', 'block', 'block'], 'noindex on a service page, blocked zoom, prechecked consent and placeholder text are blocks');
ok(a.score === 0 && a.grade === 'F' && a.counts.block === 4 && a.findings[0].sev === 'block' && a.findings[a.findings.length - 1].sev === 'note', 'the score bottoms out and the findings come sorted, blocks first', `${a.score} ${JSON.stringify(a.counts)}`);
ok(/2\.32 to 1/.test(find(a, 'a11y.contrast').evidence) && find(a, 'a11y.field_label').evidence.startsWith('q, phone') && /placeholder is not a label/.test(find(a, 'a11y.field_label').msg) && find(a, 'content.phone_not_linked').evidence === '972-555-0100' && /cdn\.one\.test\/a\.js/.test(find(a, 'perf.blocking_scripts').evidence) && find(a, 'content.broken_anchor').evidence === '#missing' && find(a, 'schema.faq_mismatch').evidence === 'Hidden question?', 'each finding quotes the thing it found');
ok(a.findings.every(f => f.info || f.fix.length > 10), 'every fault comes with a fix');
ok(has(H.audit(BAD, { url: 'http://www.bad.test/', kind: 'service' }), 'security.not_https') && !has(H.audit(BAD, { url: 'http://www.bad.test/', kind: 'service' }), 'security.mixed_content') && !ids(H.audit(BAD, { kind: 'service' })).some(i => i.startsWith('security.')), 'plain http is a block; header checks only run when headers are given, and mixed content only on an https page');

/* ---- the score: 12 for a block, 4 for a warning, 1 for a note, nothing for information, and no more than 69 with a block ---- */
const base = H.audit(GOOD, { url: 'https://www.northside.test/lp-ac-repair-plano/', kind: 'landing', brand: BRAND });
const worse = (html, o) => H.audit(html, Object.assign({ url: 'https://www.northside.test/lp-ac-repair-plano/', kind: 'landing', brand: BRAND }, o || {}));
let w = worse(GOOD.replace('<h2>The short answer</h2>', '<h2>The short answer</h2><p>TODO write this</p>'));
ok(has(w, 'content.placeholder') && w.score === Math.min(69, base.score - 12) && w.grade === 'D', 'one block caps the page at 69', `${base.score} → ${w.score}`);
w = worse(GOOD.replace(' alt="Northside Comfort technician servicing a condenser in Plano"', ''));
ok(has(w, 'a11y.img_alt') && w.score === base.score - 4 && w.areas.a11y.score === 88, 'one warning costs four points, and twelve in its own area', `${base.score} → ${w.score}, a11y ${w.areas.a11y.score}`);
w = worse(GOOD.replace(' fetchpriority="high"', ''));
ok(has(w, 'perf.hero_priority') && w.score === base.score - 1, 'one note costs one point', `${base.score} → ${w.score}`);
ok(base.findings.filter(f => f.info).length >= 1 && base.score === 100 - base.findings.filter(f => !f.info).reduce((t, f) => t + ({ block: 12, warn: 4, note: 1 })[f.sev], 0), 'information costs nothing: the score is exactly the sum of the faults');

/* ---- page kinds ---- */
ok(find(worse(GOOD, { kind: 'service' }), 'seo.noindex').sev === 'block' && find(worse(GOOD, { kind: 'other' }), 'seo.noindex').sev === 'warn', 'the same noindex is a block on a service page and a warning on an unknown kind of page');
ok(has(worse(GOOD, { kind: 'article' }), 'seo.thin_content') && !has(base, 'seo.thin_content'), 'thin content is judged by kind: fine for a landing page, short for an article');
const noCall = GOOD.replace(/<a class="btn" href="tel:[^<]*<\/a>/, '');
ok(find(worse(noCall), 'cro.phone_missing').sev === 'warn' && find(worse(noCall, { kind: 'other' }), 'cro.phone_missing').sev === 'note' && !has(worse(noCall, { kind: 'article' }), 'cro.phone_missing'), 'conversion checks are full strength on sales pages, softer on unknown pages, off on articles');
ok(has(worse(GOOD.replace(/<section id="contact">[\s\S]*?<\/section>/, '')), 'cro.form_missing') && has(worse(GOOD.replace(/<label><input type="checkbox"[\s\S]*?<\/label>/, '')), 'cro.consent_missing'), 'a landing page without a form, and a phone field without a consent box, are both raised');
ok(has(worse(GOOD.replace('<a class="btn" href="tel:+19725550100">Call (972) 555 0100</a> <a class="btn" href="#contact">Book a repair visit</a>', '')), 'cro.phone_missing') && has(worse(GOOD.replace('<p><a class="btn" href="tel:+19725550100">Call (972) 555 0100</a> <a class="btn" href="#contact">Book a repair visit</a></p>', '').replace('<h2>Request a visit</h2>', '<h2>Request a visit</h2><a href="tel:+19725550100">(972) 555 0100</a>')), 'cro.phone_not_first'), 'no phone link at all, and a phone link that only shows up further down');
ok(has(H.audit(FORGE.replace(' name="consent" value="yes" required', ' name="consent" value="yes" required checked'), { kind: 'city' }), 'cro.consent_prechecked'), 'a prechecked consent box is caught in a Site Forge form too');

/* ---- fragments ---- */
a = H.audit('<section><h1>Furnace repair in Plano</h1><a href="#elsewhere">Jump</a><a href="/a/">a</a></section>', { kind: 'other' });
ok(find(a, 'content.broken_anchor').sev === 'note' && /may sit elsewhere/.test(find(a, 'content.broken_anchor').msg), 'in a fragment a link to a missing id is only a note: the id may be on the finished page');
a = H.audit(FORGE, { kind: 'city', css: FORGE_CSS, schema: { '@graph': [SCHEMA['@graph'][0], { '@type': 'FAQPage', mainEntity: [{ '@type': 'Question', name: 'A question nobody can see?' }] }] } });
ok(has(a, 'schema.faq_mismatch') && !has(a, 'schema.not_in_markup'), 'schema handed in beside a fragment is checked against the visible questions');
ok(has(H.audit(FORGE, { kind: 'city', schema: { '@type': 'WebPage' } }), 'schema.business_missing') && has(H.audit(GOOD.replace(/,\{"@type":"FAQPage"[\s\S]*?\]\}\]\}/, ']}'), { kind: 'landing' }), 'schema.faq_missing'), 'schema with no business in it, and visible questions without FAQ markup');

/* ---- contrast and colors ---- */
eq([H.contrast('#000', '#fff').ratio, H.contrast('#000', '#fff').aaa, H.contrast('#777', 'white').ratio, H.contrast('#777', 'white').aa, H.contrast('#777', 'white').aaLarge], [21, true, 4.48, false, true], 'black on white is 21 to 1; #777 on white is 4.48 and fails AA for body text but passes for large text');
eq([H.contrast('#767676', '#ffffff').aa, H.contrast('rgb(255 255 255)', 'rgb(23, 58, 105)').ratio > 10, H.contrast('nonsense', '#fff'), H.contrast('#fff', '')], [true, true, null, null], '#767676 is the lightest gray that passes on white; a color that cannot be read gives null, not a guess');
eq([H.contrast('rgba(0,0,0,.5)', '#fff').fg, H.contrast('#000', 'rgba(0,0,0,0.5)').bg], ['#808080', '#808080'], 'see through colors are laid over what is behind them first');
eq(['#abc', '#aabbccdd', 'rgb(10, 20, 30)', 'rgba(10 20 30 / 50%)', 'hsl(0, 100%, 50%)', 'hsl(210 50% 40%)', 'navy', 'transparent', '#12', 'rgb(1,2)', ''].map(c => { const p = H.parseColor(c); return p ? H.toHex(p) + (p.a < 1 ? '@' + p.a : '') : null; }), ['#aabbcc', '#aabbcc@0.867', '#0a141e', '#0a141e@0.5', '#ff0000', '#336699', '#000080', '#000000@0', null, null, null], 'hex in 3, 6 and 8 digits, rgb, hsl, names and transparent are read; malformed colors are not');
P = H.parse('<div style="background:#000"><p style="color:#fff">light</p><div style="background:url(a.jpg)"><p style="color:#fff">on a photo</p></div><div style="background:linear-gradient(#000,#333)"><p style="color:#fff">on a gradient</p></div></div><p style="color:#999">no background known</p>');
eq([P.contrast.pairs.map(p => [p.fg, p.bg, p.pass]), P.contrast.checked, P.contrast.undetermined], [[['#ffffff', '#000000', true]], 1, 3], 'text over a photo, over a gradient, or with no background in the markup is counted as not determined, never guessed');
P = H.parse('<!doctype html><html><head><style>h2{color:#888}.card{background:#f5f5f5}.card p{color:#8a8a8a;font-size:30px}</style></head><body><h2>Big gray</h2><div class="card"><p>Large text</p><span style="color:#8a8a8a">small</span></div></body></html>');
eq(P.contrast.pairs.map(p => [p.sample, p.large, p.pass]), [['Big gray', true, true], ['Large text', true, true], ['small', false, false]], 'a whole document with its own css is read against the browser\'s white; large text needs 3 to 1, body text 4.5');

/* ---- design tokens ---- */
let d = H.design(`<!doctype html><html><head><link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Open+Sans:wght@400;700&family=Bebas+Neue&display=swap"><style>:root{--brand:#173a69}body{font-family:'Open Sans',Arial,sans-serif;color:#222;font-size:16px}.hero{background:var(--brand);color:#fff}.btn{background:#edd21c;color:#112337;border-radius:8px}.wrap{max-width:1140px}h1{font-family:"Bebas Neue",sans-serif;font-size:48px}</style></head><body><p style="color:#222;border:1px solid #ccc">x</p></body></html>`);
ok(d.colors.find(c => c.hex === '#173a69').role === 'brand token' && d.colors.find(c => c.hex === '#edd21c').role === 'button background' && d.colors.find(c => c.hex === '#222222').count === 2 && d.colors.find(c => c.hex === '#cccccc').role === 'border', 'colors come back with how often they are used and a role', JSON.stringify(d.colors));
eq([d.fonts.map(f => f.family).sort(), d.fontSizes.map(x => x.value).sort(), d.radii[0].value, d.maxWidths[0].value, d.vars], [['Arial', 'Bebas Neue', 'Open Sans'], ['16px', '48px'], '8px', '1140px', { '--brand': '#173a69' }], 'fonts (named in css or loaded from Google Fonts), sizes, radii, widths and the color variables');
eq([d.buttons[0].bg, d.buttons[0].color, d.buttons[0].radius, d.buttons[0].contrast > 4.5], ['#edd21c', '#112337', '8px', true], 'what the buttons look like, with the contrast of their label');
ok(/1 stylesheet on other URLs was not read/.test(d.notes[0]) && /No colors or fonts/.test(H.design('<p>plain</p>').notes[0]), 'the notes say what was not read');
ok(H.design(FORGE, { css: FORGE_CSS }).buttons.some(b => b.selector === '.forge-btn-primary' && b.bg === '#173a69' && b.color === '#ffffff'), 'css kept beside the markup is read, with its variables resolved');

/* ---- sanitize ---- */
const dirty = `<div onclick="x()" class="a"><a href="javascript:alert(1)" title="t">go</a><a href=" JavaScript:void(0)">x</a><img src=x.png onerror=bad() alt="i"><${S}>alert(1)</${S}><${S} src="evil.js"></${S}><${S} type="application/ld+json">{"@type":"Thing"}</${S}><meta http-equiv="refresh" content="0;url=/x"><iframe srcdoc="<p>x</p>" src="/ok"></iframe><p>kept &amp; untouched</p></div>`;
let clean = H.sanitize(dirty);
ok(!/alert|evil\.js|onclick|onerror|javascript:|refresh|srcdoc/i.test(clean) && /ld\+json">\{"@type":"Thing"\}/.test(clean) && clean.includes('<p>kept &amp; untouched</p>') && clean.includes('<a href="#" title="t">go</a>') && clean.includes('<img src="x.png" alt="i">') && clean.includes('<div class="a">'), 'scripts, handlers, javascript: links, a meta refresh and srcdoc go; JSON-LD and everything else stay', clean);
ok(H.sanitize(dirty, { scripts: true }).includes('alert(1)') && !/onclick/.test(H.sanitize(dirty, { scripts: true })) && H.sanitize(dirty, { scripts: true, handlers: true }) === dirty && H.sanitize('<p>a < b</p>') === '<p>a < b</p>', 'each kind can be kept on request, and markup with nothing to remove comes back byte for byte');

/* ---- sitemaps ---- */
eq(H.sitemapParse('<?xml version="1.0"?><sitemapindex xmlns="http://www.sitemaps.org/schemas/sitemap/0.9"><sitemap><loc>https://a.test/page-sitemap.xml</loc><lastmod>2026-01-01</lastmod></sitemap><sitemap><loc>https://a.test/post-sitemap.xml</loc></sitemap></sitemapindex>'), { kind: 'index', urls: [], sitemaps: ['https://a.test/page-sitemap.xml', 'https://a.test/post-sitemap.xml'] }, 'a sitemap index lists its child sitemaps');
eq(H.sitemapParse('<urlset><url><loc>https://a.test/</loc><lastmod>2026-10-01</lastmod></url><url><loc> https://a.test/ac-repair/?x=1&amp;y=2 </loc></url><url><loc><![CDATA[https://a.test/c/]]></loc></url><url><loc>https://a.test/</loc></url></urlset>'), { kind: 'urlset', urls: [{ loc: 'https://a.test/', lastmod: '2026-10-01' }, { loc: 'https://a.test/ac-repair/?x=1&y=2', lastmod: '' }, { loc: 'https://a.test/c/', lastmod: '' }], sitemaps: [] }, 'a urlset: entities decoded, CDATA read, white space trimmed, repeats dropped');
eq(H.sitemapParse('Home | https://a.test/\n/ac-repair/\n# a comment\nnot a url here\nhttps://a.test/sitemap.xml\na.test/contact\n/ac-repair/'), { kind: 'list', urls: [{ loc: 'https://a.test/', lastmod: '' }, { loc: '/ac-repair/', lastmod: '' }, { loc: 'a.test/contact', lastmod: '' }], sitemaps: ['https://a.test/sitemap.xml'] }, 'a plain list, one URL per line, with or without an anchor in front');
eq([H.sitemapParse('').kind, H.sitemapParse('<urlset></urlset>').kind, H.sitemapParse(null).urls.length], ['empty', 'empty', 0], 'nothing in, nothing out');

/* ---- the redirect map ---- */
let m = H.redirectMap(['https://old.test/AC-Repair.html', 'https://old.test/services/furnace-repair/', 'https://old.test/heating-and-cooling-plano', 'https://old.test/?p=123', 'https://old.test/about/', 'https://old.test/gone-forever', 'https://old.test/index.php'], ['https://old.test/ac-repair/', 'https://old.test/heating/furnace-repair/', 'https://old.test/plano-heating-cooling/', 'https://old.test/about/', 'https://old.test/contact/', 'https://old.test/']);
eq(m.rows.map(r => [r.from, r.to, r.how, r.score, !!r.same]), [['/AC-Repair.html', '/ac-repair/', 'exact', 1, false], ['/services/furnace-repair/', '/heating/furnace-repair/', 'slug', 0.9, false], ['/heating-and-cooling-plano', '/plano-heating-cooling/', 'similar', 1, false], ['/about/', '/about/', 'exact', 1, true], ['/index.php', '/', 'exact', 1, false]], 'exact once case, endings and index files are set aside; by slug when the folders moved; by shared words otherwise; an unchanged address is marked same');
eq([m.unmatched, m.unused], [['/?p=123', '/gone-forever'], ['https://old.test/contact/']], 'what found no home, and what nothing points at');
eq(H.redirectMap(['/old-page/'], ['/brand-new/'], { threshold: 0.9 }).unmatched, ['/old-page/'], 'below the threshold nothing is matched');
eq(H.redirectMap(['https://old.test/ac-repair/'], ['https://new.test/ac-repair/']).rows[0], { from: '/ac-repair/', to: 'https://new.test/ac-repair/', score: 1, how: 'exact' }, 'when the new site is on another host the target is a full URL');
eq(H.redirectMap([{ loc: 'https://a.test/x/' }], [{ loc: 'https://a.test/x' }]).rows[0].same, undefined, 'sitemap entries are accepted as they come; a trailing slash difference is a real redirect');
const rows = m.rows.concat([{ from: '/?p=123', to: '/blog/post/' }]);
let f = H.redirectFormat(rows, 'htaccess');
ok(/^# 301 redirects/.test(f) && f.includes('RewriteEngine On\nRewriteRule ^AC-Repair\\.html/?$ /ac-repair/ [R=301,L]\n') && f.includes('RewriteCond %{QUERY_STRING} ^p=123$\nRewriteRule ^/?$ /blog/post/? [R=301,L]') && !f.includes('about'), 'htaccess: one rule per moved address, the dot escaped, a query string matched with a condition, unchanged rows left out', f);
f = H.redirectFormat(rows, 'nginx');
ok(f.includes('location ~ ^/services/furnace-repair/?$ { return 301 /heating/furnace-repair/; }') && /# \/\?p=123 -> \/blog\/post\//.test(f), 'nginx: a location per address, and a comment where a query string needs a map', f);
eq(H.redirectFormat(rows, 'netlify').split('\n').slice(0, 2).concat(H.redirectFormat(rows, 'netlify').split('\n')[4]), ['/AC-Repair.html  /ac-repair/  301', '/services/furnace-repair  /heating/furnace-repair/  301', '/ p=123  /blog/post/  301'], 'netlify: source, target, 301, with a query written as a parameter match');
eq(H.redirectFormat(rows, 'csv').split('\n').slice(0, 2), ['source,target,regex,code', '"/AC-Repair.html","/ac-repair/",0,301'], 'csv: the four columns the Redirection plugin imports');
let threw = ''; try { H.redirectFormat(rows, 'iis'); } catch (e) { threw = e.message; }
ok(/Unknown redirect format "iis"/.test(threw), 'an unknown format is refused by name');

/* ---- the static site bundle ---- */
const SITE = { site: { name: 'Northside Comfort', url: 'https://www.northside.test/', lang: 'en', phone: '(972) 555 0100', brand: { primary: '#173a69', accent: '#edd21c', dark: '#112337', fontHeading: 'Bebas Neue', fontBody: 'Open Sans' } },
  pages: [
    { slug: 'home', title: 'Northside Comfort', html: '<section><h1>Home</h1><a href="/ac-repair/">AC repair</a> <a href="/areas/plano/#faq">Plano</a> <a href="/missing/">x</a> <a href="https://www.northside.test/lp-offer/">offer</a> <a href="https://other.test/">out</a><img src="img/a.webp" alt="a"></section>', css: '.x{color:red}', schema: { '@type': 'HVACBusiness', name: 'N <b>' }, seo: { og_image: 'https://www.northside.test/og.webp' } },
    { slug: 'ac-repair', title: 'AC Repair', html: '<section><h1>AC repair</h1><a href="/">home</a><form action="/wp-json/forge/v1/lead"></form></section>', css: '.x{color:red}', seo: { title: 'AC Repair in Plano | Northside Comfort', description: 'Fast AC repair & more.' } },
    { slug: '/areas/Plano/', title: 'Plano', html: '<section id="faq"><h1>Plano</h1><a href="/ac-repair/">AC</a> <a href="#faq">here</a> <a href="tel:+19725550100">call</a></section>', css: '.y{color:blue}' },
    { slug: 'lp-offer', title: 'Offer', html: '<h1>Offer</h1>', seo: { noindex: true } }],
  redirects: [{ from: 'https://www.northside.test/old-ac.html', to: '/ac-repair/' }, { from: '/same/', to: '/same/' }], notes: 'Built for the test.' };
let B = H.siteBundle(SITE); const file = n => (B.find(e => e.name === n) || {}).data;
eq(B.map(e => e.name), ['index.html', 'ac-repair/index.html', 'areas/plano/index.html', 'lp-offer/index.html', 'assets/site.css', '404.html', 'sitemap.xml', 'robots.txt', '_redirects', '.htaccess', 'README.txt'], 'one index.html per page in its slug folder, the home page at the root, then the shared files');
ok(B.every(e => typeof e.data === 'string' && e.data.length > 0) && !Object.keys(B).includes('report') && B.report.pages.length === 4, 'every entry is text for the zip writer; the report rides along without showing up in a loop');
ok(file('index.html').includes('<a href="ac-repair/index.html">AC repair</a> <a href="areas/plano/index.html#faq">Plano</a> <a href="/missing/">x</a> <a href="lp-offer/index.html">offer</a> <a href="https://other.test/">out</a>'), 'at the root, links to pages of the bundle become relative file links (a full URL on the site\'s own host too); other links stay', file('index.html').split('<main')[1].slice(0, 300));
ok(file('ac-repair/index.html').includes('<a href="../index.html">home</a>') && file('ac-repair/index.html').includes('href="../assets/site.css"'), 'one folder down, links and the stylesheet climb one level');
ok(file('areas/plano/index.html').includes('<a href="../../ac-repair/index.html">AC</a> <a href="#faq">here</a> <a href="tel:+19725550100">call</a>') && file('areas/plano/index.html').includes('href="../../assets/site.css"') && file('areas/plano/index.html').includes('<a class="site-name" href="../../index.html">'), 'two folders down they climb two; anchors and phone links are left alone');
const exists = new Set(B.map(e => e.name));
ok(B.filter(e => /index\.html$/.test(e.name)).every(e => [...e.data.matchAll(/href="((?:\.\.\/)*[^":#]*?index\.html|(?:\.\.\/)*assets\/site\.css)(#[^"]*)?"/g)].every(mm => exists.has(path.posix.normalize(path.posix.join(path.posix.dirname(e.name), mm[1]))))), 'every relative link in every page resolves to a file in the bundle, so the site works from a folder on disk');
ok(/<nav class="site-nav" aria-label="Main"><ul><li><a href="\.\.\/index\.html">Home<\/a><\/li><li><a href="\.\.\/ac-repair\/index\.html" aria-current="page">AC Repair<\/a><\/li><li><a href="\.\.\/areas\/plano\/index\.html">Plano<\/a><\/li><\/ul><\/nav>/.test(file('ac-repair/index.html')), 'the default navigation lists the indexable pages and marks the current one', file('ac-repair/index.html').match(/<nav[\s\S]*?<\/nav>/)[0]);
ok(file('index.html').startsWith('<!doctype html>\n<html lang="en">') && file('index.html').includes('<a class="site-skip" href="#main">Skip to content</a>') && file('index.html').includes('<main id="main">') && file('index.html').includes('<a class="site-call" href="tel:+19725550100">Call (972) 555 0100</a>') && file('index.html').includes('<footer class="site-footer">'), 'each page is a whole document with a skip link, a main landmark, a call button and a footer');
ok(file('ac-repair/index.html').includes('<title>AC Repair in Plano | Northside Comfort</title>') && file('ac-repair/index.html').includes('<meta name="description" content="Fast AC repair &amp; more.">') && file('ac-repair/index.html').includes('<link rel="canonical" href="https://www.northside.test/ac-repair/">') && file('index.html').includes('<link rel="canonical" href="https://www.northside.test/">') && file('index.html').includes('<meta property="og:image" content="https://www.northside.test/og.webp">'), 'title, description, canonical and Open Graph tags are written, escaped');
ok(file('index.html').includes('<script type="application/ld+json">{"@type":"HVACBusiness","name":"N \\u003cb>"}</script>'), 'JSON-LD is embedded with "<" escaped so it cannot close the script');
ok(file('lp-offer/index.html').includes('<meta name="robots" content="noindex,follow">') && !file('sitemap.xml').includes('lp-offer') && (file('sitemap.xml').match(/<loc>/g) || []).length === 3 && file('sitemap.xml').includes('<loc>https://www.northside.test/areas/plano/</loc>') && file('robots.txt') === 'User-agent: *\nAllow: /\nSitemap: https://www.northside.test/sitemap.xml\n', 'a noindex page says so and stays out of the sitemap; robots.txt points at the sitemap');
ok(file('_redirects') === '/old-ac.html  /ac-repair/  301\n' && file('.htaccess').startsWith('DirectoryIndex index.html\nErrorDocument 404 /404.html\n') && file('.htaccess').includes('RewriteRule ^old-ac\\.html/?$ /ac-repair/ [R=301,L]') && !file('.htaccess').includes('same'), 'the redirect files carry the redirects, minus any that go nowhere new');
ok(file('404.html').includes('href="/assets/site.css"') && file('404.html').includes('<a href="/">home page</a>') && file('404.html').includes('<meta name="robots" content="noindex">') && file('404.html').includes('<a href="/ac-repair/">AC Repair</a>'), 'the 404 page uses addresses from the site root, since it is served at any depth');
const css = file('assets/site.css');
ok(css.startsWith(':root{--site-primary:#173a69;--site-accent:#edd21c;--site-dark:#112337;--site-on-dark:#ffffff;--site-on-accent:#111111;') && css.includes("--site-font-b:'Open Sans',system-ui") && css.includes("--site-font-h:'Bebas Neue',system-ui") && css.split('.x{color:red}').length === 2 && css.includes('.y{color:blue}') && css.includes('prefers-reduced-motion') && css.includes(':focus-visible'), 'one stylesheet: the brand as variables, a readable text color chosen for the accent, each page\'s css once, focus and reduced motion handled');
ok(H.contrast('#111111', '#edd21c').aa && H.contrast('#ffffff', '#112337').aa, 'the colors it chose for the call button and the header pass AA');
const readme = file('README.txt');
ok(/a static site of 4 pages/.test(readme) && /lp-offer\/index\.html  \/lp-offer\/  noindex/.test(readme) && /PUT IT ONLINE/.test(readme) && /\/ac-repair\/ posts to \/wp-json\/forge\/v1\/lead/.test(readme) && /A static host has no WordPress/.test(readme) && /not in this bundle[^\n]*: \/missing\/\./.test(readme) && /img\/a\.webp/.test(readme) && /names the fonts Bebas Neue and Open Sans but does not load them/.test(readme) && /Built for the test\./.test(readme), 'the README says how to deploy and names what to check: the WordPress form, the link and the image that are not in the bundle, the fonts', readme);
eq([B.report.outside, B.report.forms, B.report.images, B.report.pages[2]], [['/missing/'], [{ page: '/ac-repair/', action: '/wp-json/forge/v1/lead', wordpress: true }], [{ page: '/', src: 'img/a.webp' }], { slug: 'areas/plano', path: '/areas/plano/', file: 'areas/plano/index.html', noindex: false }], 'the report carries the same facts as data');
/* without a site URL, with a custom nav and footer, and the error cases */
B = H.siteBundle({ site: { name: 'Plain' }, pages: [{ title: 'Start', html: '<h1>Start</h1>', isHome: true }, { title: 'About Us', html: '<h1>About</h1>' }], nav: [{ label: 'About', href: 'about-us' }, { label: 'Call', href: 'tel:+19725550100' }, { label: 'Blog', href: 'https://blog.test/' }], footerHtml: '<p>Custom footer</p>', headHtml: '<meta name="theme-color" content="#173a69">' });
eq(B.map(e => e.name), ['index.html', 'about-us/index.html', 'assets/site.css', '404.html', 'robots.txt', 'README.txt'], 'with no site URL there is no sitemap and no redirect file; a page without a slug is named from its title');
ok(!B[0].data.includes('rel="canonical"') && B[0].data.includes('<li><a href="about-us/index.html">About</a></li><li><a href="tel:+19725550100">Call</a></li><li><a href="https://blog.test/">Blog</a></li>') && B[1].data.includes('<li><a href="../about-us/index.html" aria-current="page">About</a></li>') && B[0].data.includes('<p>Custom footer</p>') && B[0].data.includes('<meta name="theme-color" content="#173a69">') && !B[0].data.includes('site-call') && !B[0].data.includes('aria-current') && /No site URL was given/.test(B[5].data) && B[4].data === 'User-agent: *\nAllow: /\n' && B[3].data.includes('<li><a href="/about-us/">About</a></li>'), 'a custom navigation takes slugs, phone links and outside URLs (never marked as the current page); the footer and extra head markup are used as given', B[0].data.match(/<nav[\s\S]*?<\/nav>/)[0]);
const fails = fn => { try { fn(); return ''; } catch (e) { return e.message; } };
ok(/at least one page/.test(fails(() => H.siteBundle({ pages: [] }))) && /share the address \/a\//.test(fails(() => H.siteBundle({ pages: [{ slug: 'home', html: 'x' }, { slug: 'a', html: 'x' }, { slug: 'A', html: 'y' }] }))) && /neither a slug nor a title/.test(fails(() => H.siteBundle({ pages: [{ slug: 'home', html: 'x' }, { html: 'y' }] }))), 'no pages, two pages at one address, and a page with no name are refused with the reason');
ok(H.siteBundle({ site: { brand: { primary: 'javascript:1', accent: 'not-a-color', fontBody: 'Evil";}<x>' } }, pages: [{ slug: 'home', html: '<p>x</p>' }] }).find(e => e.name === 'assets/site.css').data.startsWith(":root{--site-primary:#13243a;--site-accent:#0b6f6d;--site-dark:#0e1a26;--site-on-dark:#ffffff;--site-on-accent:#ffffff;--site-font-b:'Evilx',"), 'brand values that are not colors fall back, and a font name cannot break out of the stylesheet');
/* the bundle's own output holds up under the audit: a Site Forge page shipped as a static home page */
B = H.siteBundle({ site: SITE.site, pages: [{ slug: 'home', title: 'Home', html: FORGE, css: FORGE_CSS, schema: SCHEMA, isHome: true, seo: { title: 'Plano AC Repair and Replacement | Northside Comfort', description: 'AC repair and replacement, furnaces and heat pumps for Plano homes from Northside Comfort. Written prices before work starts.', og_image: 'https://www.northside.test/og.webp' } }, { slug: 'ac-repair', title: 'AC repair', html: '<h1>AC repair</h1>' }, { slug: 'furnace-repair', title: 'Furnace repair', html: '<h1>Furnace repair</h1>' }] });
a = H.audit(B[0].data, { kind: 'city', brand: BRAND, url: 'https://www.northside.test/', css: B.find(e => e.name === 'assets/site.css').data });
ok(a.counts.block === 0 && a.counts.warn === 0 && a.score >= 98 && a.facts.contrast.failing === 0 && a.facts.contrast.checked > 20 && !a.fragment, 'a page the bundle writes passes the audit as a whole document, header, footer and colors included', `${a.score} ${JSON.stringify(a.counts)} ${a.findings.filter(x => !x.info).map(x => x.id + ' [' + x.evidence + ']').join(' ')} ${JSON.stringify(a.facts.contrast)}`);
ok(B[0].data.includes('<p>Northside Comfort · <a href="tel:+19725550100">(972) 555 0100</a></p>'), 'the default footer links the phone number');
/* ---- the rest of the findings, on a second page built to trip them, and proof that none is left untested ---- */
const BAD2 = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="description" content="Too short."><link rel="stylesheet" href="/1.css"><link rel="stylesheet" href="/2.css"><link rel="stylesheet" href="/3.css"><link rel="stylesheet" href="/4.css"><link rel="stylesheet" href="/5.css"></head><body><main>
<section><p>Welcome to our company. We do many things for many people across the region and we would love to hear from you soon.</p></section>
<section><h2></h2><h2>Details</h2><button></button><a href="tel:+19725550100">(972) 555 0100</a><img src="one.webp" alt="one" width="10" height="10"><img src="two.webp" alt="two" width="10" height="10"><iframe src="https://maps.test/e" title="Map"></iframe>${'<span>x</span>'.repeat(900)}</section></main><${S}>${'var a = 1;'.repeat(7000)}</${S}></body></html>`;
a = H.audit(BAD2, { kind: 'home', url: 'https://www.northside.test/' });
const rest = ['seo.title_missing', 'seo.viewport_missing', 'seo.meta_length', 'seo.canonical_missing', 'seo.h1_missing', 'seo.no_internal_links', 'a11y.heading_empty', 'a11y.button_name', 'a11y.tap_target', 'perf.css_requests', 'perf.dom_size', 'perf.iframe_not_lazy', 'perf.img_not_lazy', 'perf.inline_bytes', 'cro.cta_missing_first', 'cro.phone_not_first', 'cro.trust_hours'];
ok(rest.every(id => has(a, id)), 'a page with no title, no viewport, no h1, no call to action up top, heavy inline script and a deep tree trips the remaining findings', rest.filter(id => !has(a, id)).join(', '));
eq([find(a, 'seo.title_missing').sev, find(a, 'seo.viewport_missing').sev, find(a, 'seo.h1_missing').sev, find(a, 'perf.dom_size').sev, find(a, 'a11y.tap_target').info, find(a, 'cro.trust_hours').info, a.score <= 69], ['block', 'block', 'block', 'note', true, true, true], 'a missing title, viewport or h1 is a block; tap size and hours are information only');
const known = [...new Set([...source.matchAll(/add\('([a-z0-9_]+\.[a-z0-9_]+)'/g)].map(x => x[1]))];
