/* an area the caller cannot judge is left out of the findings and the score */
{
  const page = '<section><h1>Furnace repair</h1><img src="a.jpg" alt="A furnace" loading="lazy"><p>Call <a href="tel:+19725550100">972 555 0100</a>.</p></section>';
  const full = H.audit(page, { fragment: true, kind: 'landing' }), cut = H.audit(page, { fragment: true, kind: 'landing', skipAreas: ['perf', 'nonsense'] });
  ok(full.findings.some(f => f.area === 'perf') && !cut.findings.some(f => f.area === 'perf') && cut.areas.perf.skipped === true && cut.areas.perf.score === null && cut.score > full.score && cut.skipped.includes('perf (not scored)') && cut.areas.seo.score === full.areas.seo.score, 'skipAreas removes an area from the findings and the score and reports it as not scored', `${full.score} → ${cut.score}`);
}

/* a regulator's numbers in a required notice are not the business's phone: only the loose number in the copy is reported */
{
  const page = '<section><h1>Furnace repair</h1><p>Call 972-555-0100 today.</p></section><section id="notice" class="forge-section"><p>Regulated by the Texas Department of Licensing and Regulation, 1-800-803-9202, 512-463-6599.</p></section><p class="legal-note">Questions: 214-555-0199</p>';
  const f = H.audit(page, { fragment: true, kind: 'landing' }).findings.find(x => x.id === 'content.phone_not_linked');
  ok(f && f.evidence === '972-555-0100', 'phone numbers inside a notice, legal or disclaimer block are not reported as missing a link', f && f.evidence);
}
